#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_test_successful_calculation(void) {
    // The test function is static, so we cannot call it directly from another file.
    // However, the path shows the exact sequence of operations.
    // We will replicate the sequence and verify the results.
    node *root = NULL;

    // Insert the five predefined processes
    insert(&root, 1, 0, 5, 1);
    insert(&root, 2, 1, 4, 2);
    insert(&root, 3, 2, 3, 3);
    insert(&root, 4, 3, 2, 4);
    insert(&root, 5, 4, 1, 5);

    // Calculate averages
    float avgCT = calculate_ct(&root);
    float avgTAT = calculate_tat(&root);
    float avgWT = calculate_wt(&root);

    // Assert expected values (as per the original test)
    TEST_ASSERT_EQUAL_FLOAT(11.0f, avgCT);
    TEST_ASSERT_EQUAL_FLOAT(9.0f, avgTAT);
    TEST_ASSERT_EQUAL_FLOAT(6.0f, avgWT);

    // Cleanup: free the entire list
    // Since there is no provided function to free the whole list, we must traverse and free each node.
    node *current = root;
    node *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_test_successful_calculation);
    return UNITY_END();
